CREATE TABLE public.ventio_identity_device_activity (tenant_id text NOT NULL, device_id text NOT NULL, actor_id text NOT NULL, last_authenticated_at timestamptz NOT NULL, authentication_count bigint NOT NULL DEFAULT 1, PRIMARY KEY (tenant_id, device_id), FOREIGN KEY (tenant_id, device_id, actor_id) REFERENCES public.ventio_identity_devices (tenant_id, device_id, actor_id), CHECK (authentication_count > 0));
